mapper.select:
select t.spec_cd,t.spec_cd specCd,t.status_cd,t.status_cd statusCd,t.param_id,t.param_id
paramId,t.template_id,t.template_id templateId,t.community_id,t.community_id
communityId,t.param_value,t.param_value paramValue
from event_template_param t
where 1 =1

    and t.spec_cd= #{specCd}


    and t.status_cd= #{statusCd}


    and t.param_id= #{paramId}


    and t.template_id= #{templateId}


    and t.community_id= #{communityId}


    and t.param_value= #{paramValue}

order by t.create_time desc

    limit #{page}, #{row}

